  <button className="product-image" onClick={()=>{if(!swiped.current)onOpen(index)}} aria-label={`Ver detalles y fotos de ${product.name}`}><ProductArtwork product={product} photoIndex={index}/><span className="catalog-photo-open"><Search size={14}/> Ver de cerca</span></button>
